// seed: tests/seed.user.spec.ts
// Веб-мок ?mock=outOfFrame: ~25 с в кадре 60% воды, затем снова 100%. Проверяет окно/тексты и авто-возврат по мок-сигналу;
// распознавание реального поворота телефона и «המצלמה מוסתרת» (палец на объективе) — только вручную на телефоне (MON-030, MON-031).
import { test, expect } from '@playwright/test';
import path from 'node:path';
import { startMonitoring, endMonitoring } from '../helpers/monitor';

test.use({ storageState: path.join(__dirname, `../../../auth/${process.env.QA_MON_AUTH || 'user'}.json`) });
test.setTimeout(150_000);

test.describe('Сбои мониторинга (мок)', () => {
  test('Вода вне кадра: «הבריכה נחתכה» · «לא במעקב» + «כיוון מחדש», вода вернулась — «הניטור חזר לפעול» #15ae4b @iphone @data', async ({ page }) => {
    await startMonitoring(page, 'outOfFrame');

    // Сбой (тикет «מה רצוי»: … → «לא במעקב» + «כוונו את המצלמה מחדש»; Figma 10.3)
    await expect(page.getByText('הבריכה נחתכה').filter({ visible: true }).first()).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(/הבריכה לא במעקב — השגיחו עליה בעצמכם/).filter({ visible: true }).first()).toBeVisible();
    await expect(page.getByText('חלק מהבריכה יצא מהתמונה. נסו לפי הסדר:').filter({ visible: true }).first()).toBeVisible();
    await expect(page.getByRole('button', { name: 'כיוון מחדש' }).filter({ visible: true }).first()).toBeVisible();

    // Вода снова в кадре → сбой снимается сам (реджект 05.11: «חזר לפעול» רק כשהבריכה שוב בתמונה)
    await expect(page.getByText('הניטור חזר לפעול').filter({ visible: true }).first()).toBeVisible({ timeout: 40_000 });
    await expect(page.getByText('תקין', { exact: true }).filter({ visible: true }).first()).toBeVisible();
    await expect(page.getByText('הבריכה נחתכה').filter({ visible: true })).toHaveCount(0);

    await endMonitoring(page);
  });
});
